css:
.print-format-doc.print-format-doc--standard {
	font-size: 0.92em;
}
.print-format-doc.print-format-doc--standard .field + .field {
	margin-top: 0.3em;
}
.print-format-doc.print-format-doc--standard .section-label {
	font-size: 1em;
	border-bottom: 1px solid var(--gray-900);
	margin-bottom: 0.5em;
}
.print-format-doc.print-format-doc--standard .child-table .table thead th {
	border-bottom: 1.5px solid var(--gray-900) !important;
}
.print-format-doc.print-format-doc--standard .child-table--striped .table .even td {
	background-color: var(--gray-100) !important;
}
